UPDATE sv_document_indexing_task
SET attempt = #{attempt},
    status = #{status},
    error_message = #{errorMessage},
    callback_received_at = #{callbackReceivedAt}
WHERE task_id = #{taskId}
  AND (
      attempt < #{attempt}
      OR (attempt = #{attempt} AND status NOT IN ('COMPLETED', 'FAILED'))
  )
